def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return
    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65
    max_force = 42.0
    max_impulse = 4.2
    dead_zone_threshold = 0.3  # Reduced to handle dead zone more effectively
    wind_period = 8.0  # Estimated wind period based on observed oscillations
    wind_strength = 25.0  # Increased to counteract stronger wind

    # Check if in target zone
    if pos.y >= target_y and target_x_min <= pos.x <= target_x_max:
        if abs(vx) < 1.0 and vy < 0:
            # Success at apex
            return
        elif abs(vx) < 1.35 and vy <= 0:
            # Success via vertical fall
            return

    # Estimate wind direction and apply counterforce
    t = sandbox.get_sim_time()
    wind_phase = (2 * math.pi * t) / wind_period
    wind_dir = math.sin(wind_phase)
    wind_counter_force = -wind_dir * wind_strength
    net_force_x = 0

    # Determine desired horizontal direction based on target x range
    if pos.x < target_x_min:
        desired_force_x = max_force  # Move right
    elif pos.x > target_x_max:
        desired_force_x = -max_force  # Move left
    else:
        desired_force_x = 0  # No horizontal force needed if in target x range

    # Adjust for wind counteraction
    net_force_x = desired_force_x + wind_counter_force
    if abs(net_force_x) <= max_force:
        sandbox.apply_force_to_seat(net_force_x, 0)
    else:
        # Clamp to max force if wind force is too strong
        if net_force_x > 0:
            sandbox.apply_force_to_seat(max_force, 0)
        else:
            sandbox.apply_force_to_seat(-max_force, 0)

    # Handle dead zone by applying impulse to overcome suppression
    if abs(vx) < dead_zone_threshold:
        # Apply impulse to get horizontal speed up
        if pos.x < target_x_min:
            sandbox.apply_impulse_to_seat(0, max_impulse)
        elif pos.x > target_x_max:
            sandbox.apply_impulse_to_seat(0, -max_impulse)
        else:
            # Apply vertical impulse if near the bottom
            if vy < 0 and abs(vy) < 0.1:
                sandbox.apply_impulse_to_seat(0, max_impulse)
    else:
        # Apply vertical impulse at the bottom of the swing
        if vy < 0 and abs(vy) < 0.1:
            sandbox.apply_impulse_to_seat(0, max_impulse)
